def build_container(self):
        tag = f'{self.registry}:{self.milk_uuid}'
        self.client.images.build(
            path=self.filepaths['SOURCE_REPO_PATH'],
            dockerfile=self.filepaths['DOCKERFILE_PATH'],
            tag=tag,
            rm=True,
            buildargs={
                'REQUIREMENTS_PATH': self.filepaths['REQUIREMENTS_PATH']
            }
        )
        return tag
